// Settings text for a language, with English for anything missing. {name} placeholders are filled from vars.
globalThis.FN_st = (lang, key, vars = {}) => {
  const all = globalThis.FN_SETTINGS_I18N;
  let s = (all[lang] && all[lang][key]) ?? all.en[key] ?? key;
  for (const [k, v] of Object.entries(vars)) s = s.replace(`{${k}}`, v);
  return s;
};

